INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2350, 'poverty', '/ˈpɒvərti/', 'noun', '{"zh-TW":["貧窮；貧困","貧窮"],"en":["the state of being very poor","the state of being poor"]}', NULL, 'poverty line / poverty rate / live in poverty; poverty level / reduce poverty', '[{"en":"The poverty rate has decreased.","zh-TW":"貧困率已下降。"},{"en":"Many families live below the poverty line.","zh-TW":"許多家庭生活在貧窮線以下。"},{"en":"Reducing poverty requires collective effort.","zh-TW":"減少貧困需要集體努力。"},{"en":"The poverty rate dropped by 3%.","zh-TW":"貧困率下降了3%。"}]', '{"adjective":"impoverished"}', NULL, 3, 2350, NULL),
(2351, 'power', '/ˈpaʊər/', 'noun', '{"zh-TW":["力量；權力；電力"],"en":["ability to act","authority","electricity"]}', NULL, 'purchasing power / power outage', '[{"en":"Consumer purchasing power has declined.","zh-TW":"消費者購買力下降了。"},{"en":"A power outage disrupted operations.","zh-TW":"停電影響了營運。"}]', '{"noun":"power","adjective":"powerful","adjective2":"powerless","verb":"empower"}', NULL, 2, 2351, NULL),
(2352, 'PPC', '/ˌpiː piː ˈsiː/', 'noun', '{"zh-TW":["按點擊付費廣告"],"en":["pay-per-click; a digital advertising model where advertisers pay per click"]}', NULL, 'PPC campaign / PPC advertising / manage PPC / PPC budget', '[{"en":"The PPC campaign drove targeted traffic to the product page.","zh-TW":"按點擊付費廣告活動為產品頁面帶來了定向流量。"},{"en":"Effective PPC management can yield a strong return on ad spend.","zh-TW":"有效的PPC管理可以產生強勁的廣告支出回報。"}]', '{"full form":"pay-per-click"}', NULL, 1, 2352, NULL),
(2353, 'practical', 'ˈpræktɪkəl', 'adjective', '{"zh-TW":["實際的；實用的","可行的"],"en":["relating to real situations","sensible and realistic"]}', NULL, 'practical experience/practical solution', '[{"en":"We need a practical approach.","zh-TW":"我們需要一個實際的方法。"}]', '{"noun":"practicality","adverb":"practically"}', NULL, 3, 2353, NULL),
(2354, 'practice', '/ˈpræktɪs/', 'noun', '{"zh-TW":["實踐；慣例"],"en":["the actual doing of something; a habitual way"]}', NULL, 'best practice / put into practice / standard practice', '[{"en":"This is standard practice in our industry.","zh-TW":"這是我們行業的標準做法。"},{"en":"We put the theory into practice.","zh-TW":"我們將理論付諸實踐。"}]', '{"verb":"practice, practise","adjective":"practical","adverb":"practically","noun":"practitioner"}', NULL, 3, 2354, 416),
(2355, 'practitioner', '/prækˈtɪʃənər/', 'noun', '{"zh-TW":["從業者；實踐者"],"en":["a person who practices a profession or occupation"]}', NULL, 'legal practitioner / HR practitioner / experienced practitioner', '[{"en":"The workshop was led by an experienced HR practitioner.","zh-TW":"研討會由一位有經驗的人力資源從業者主持。"},{"en":"Legal practitioners must comply with strict professional conduct rules.","zh-TW":"法律從業者必須遵守嚴格的職業操守規則。"}]', '{"noun":"practice"}', NULL, 4, 2355, NULL),
(2356, 'pre-approved', 'priː əˈpruːvd', 'adjective', '{"zh-TW":["預先批准的；事先獲批的","已審核的"],"en":["approved in advance","already agreed to"]}', NULL, 'pre-approved budget/pre-approved vendor', '[{"en":"Use pre-approved suppliers only.","zh-TW":"請只使用預先批准的供應商。"}]', NULL, NULL, 4, 2356, NULL),
(2357, 'precaution', '/prɪˈkɔːʃən/', 'noun', '{"zh-TW":["預防措施"],"en":["an action taken to prevent something bad"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"caution","meaning":"warning (警告)"}}', 'take precautions / safety precaution / as a precaution', '[{"en":"We take every precaution to ensure safety.","zh-TW":"我們採取一切預防措施確保安全。"},{"en":"As a precaution, please back up your files.","zh-TW":"作為預防，請備份文件。"}]', '{"adjective":"precautionary"}', NULL, 4, 2357, NULL),
(2358, 'precede', '/prɪˈsiːd/', 'verb', '{"zh-TW":["在...之前"],"en":["to come before in time or order"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"cede","meaning":"go (走)"}}', 'precede sth. / preceding year / as preceded by', '[{"en":"A brief introduction preceded the main speech.","zh-TW":"簡短介紹在主要演講之前。"},{"en":"In the preceding quarter, sales were strong.","zh-TW":"在前一季度，銷售強勁。"}]', '{"adjective":"preceding, precedent","noun":"precedent, precedence"}', NULL, 3, 2358, NULL),
(2359, 'precedent', '/ˈprɛsɪdənt/', 'noun', '{"zh-TW":["先例"],"en":["an earlier event or action used as an example"]}', NULL, 'set a precedent / legal precedent', '[{"en":"This case sets an important precedent.","zh-TW":"這個案件開創了重要的先例。"},{"en":"There is no precedent for this situation.","zh-TW":"這種情況沒有先例可循。"}]', '{"adjective":"unprecedented"}', NULL, 3, 2359, NULL),
(2360, 'precipitation', '/prɪˌsɪpɪˈteɪʃn/', 'noun', '{"zh-TW":["降水"],"en":["rain, snow, sleet, or hail that falls to the ground"]}', '{"prefix":{"text":"pre-","meaning":"before (前)"},"root":{"text":"cipit","meaning":"head/fall (頭/落下)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"頭朝下落下的過程，即「降水」。"}', 'annual precipitation / heavy precipitation', '[{"en":"The annual precipitation in this area is 1200mm.","zh-TW":"這個地區年降水量為1200毫米。"},{"en":"Heavy precipitation is expected overnight.","zh-TW":"預計夜間會有大量降水。"}]', '{"verb":"precipitate"}', NULL, 5, 2360, NULL),
(2361, 'precise', '/prɪˈsaɪs/', 'adjective', '{"zh-TW":["精確的；準確的"],"en":["exact and accurate"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"cise","meaning":"cut (切)"}}', 'precise measurement / to be precise / precise instructions', '[{"en":"Please give me the precise figures.","zh-TW":"請給我精確數據。"},{"en":"To be precise, the total is $45,231.","zh-TW":"準確地說，總數是$45,231。"}]', '{"adverb":"precisely","noun":"precision"}', NULL, 3, 2361, NULL),
(2362, 'predecessor', '/ˈpredəsesər/', 'noun', '{"zh-TW":["前任；前身"],"en":["a person or thing that came before another in a role or position"]}', NULL, 'my predecessor / predecessor company / predecessor system', '[{"en":"She inherited a well-run team from her predecessor.","zh-TW":"她從前任那裡繼承了一支管理有序的團隊。"},{"en":"The new system replaced the predecessor which was installed in 2010.","zh-TW":"新系統取代了2010年安裝的前身系統。"}]', '{"opposite":"successor"}', NULL, 4, 2362, NULL),
(2363, 'predict', '/prɪˈdɪkt/', 'verb', '{"zh-TW":["預測","預測；預言"],"en":["to say what will happen in the future"]}', '{"prefix":{"text":"pre-","meaning":"before (在前)"},"root":{"text":"dict","meaning":"say (說)"},"logic":"事先說出，即「預測」。"}', 'predict the outcome / predict the future / hard to predict; predict the outcome / predict growth / as predicted', '[{"en":"Experts predict the economy will grow next year.","zh-TW":"專家預測明年經濟將成長。"},{"en":"It''s difficult to predict the weather accurately.","zh-TW":"精準預測天氣很困難。"},{"en":"Analysts predict strong growth next quarter.","zh-TW":"分析師預測下季度強勁增長。"},{"en":"It is difficult to predict market trends.","zh-TW":"很難預測市場趨勢。"}]', '{"noun":"prediction","adjective":"predictable","adverb":"predictably"}', NULL, 3, 2363, NULL),
(2364, 'predominant', '/prɪˈdɒmɪnənt/', 'adjective', '{"zh-TW":["主要的；佔優勢的"],"en":["most common or most powerful"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"domin","meaning":"rule (統治)"},"suffix":{"text":"-ant","meaning":"...的"}}', 'predominant factor / predominant view', '[{"en":"Cost is the predominant factor in their decision.","zh-TW":"成本是他們決定的主要因素。"},{"en":"English is the predominant language in business.","zh-TW":"英語是商務中的主要語言。"}]', '{"adverb":"predominantly","verb":"predominate"}', NULL, 4, 2364, NULL),
(2365, 'prefer', '/prɪˈfɜːr/', 'verb', '{"zh-TW":["偏好；更喜歡"],"en":["to like one thing more than another"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"fer","meaning":"carry (攜帶)"}}', 'prefer A to B / prefer to do', '[{"en":"Most clients prefer email communication.","zh-TW":"多數客戶偏好電郵溝通。"},{"en":"I prefer to work from home on Fridays.","zh-TW":"我偏好週五在家工作。"}]', '{"noun":"preference","adjective":"preferable, preferred","adverb":"preferably"}', NULL, 2, 2365, NULL),
(2366, 'preliminary', '/prɪˈlɪmɪneri/', 'adjective', '{"zh-TW":["初步的；預備的"],"en":["coming before the main part"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"limin","meaning":"threshold (門檻)"}}', 'preliminary results / preliminary investigation', '[{"en":"Preliminary results indicate success.","zh-TW":"初步結果顯示成功。"},{"en":"A preliminary review was conducted.","zh-TW":"進行了初步審查。"}]', '{"noun":"preliminary"}', NULL, 4, 2366, 418),
(2367, 'premiere', '/prɪˈmɪər/', 'noun', '{"zh-TW":["首映；首演"],"en":["the first public showing of a movie or performance"]}', '{"prefix":{"text":"pre-","meaning":"first (第一)"},"root":{"text":"miere","meaning":"first (最初)"},"logic":"最初的公開展演，即「首映」。"}', 'movie premiere / world premiere', '[{"en":"The movie premiere attracted many celebrities.","zh-TW":"電影首映吸引了許多名人。"},{"en":"The play had its world premiere in London.","zh-TW":"這齣戲在倫敦舉行了世界首演。"}]', '{"verb":"premiere"}', NULL, 3, 2367, NULL),
(2368, 'premise', '/ˈprɛmɪs/', 'noun', '{"zh-TW":["前提","場所"],"en":["a statement assumed to be true","a building and its land"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"mis","meaning":"send (送)"}}', 'on the premise that / business premises', '[{"en":"The plan is based on the premise that sales will grow.","zh-TW":"計劃以銷售將增長為前提。"},{"en":"Smoking is not allowed on the premises.","zh-TW":"場所內禁止吸煙。"}]', NULL, NULL, 3, 2368, NULL),
(2369, 'premises', '/ˈpremɪsɪz/', 'noun', '{"zh-TW":["房舍；場地"],"en":["a building and the land it occupies, especially when used for business"]}', NULL, 'business premises / vacate the premises / on the premises', '[{"en":"All visitors must sign in before entering the premises.","zh-TW":"所有訪客在進入場地前必須登記。"},{"en":"The company relocated to larger premises downtown.","zh-TW":"公司搬遷到市中心更大的辦公場所。"}]', NULL, NULL, 3, 2369, NULL),
(2370, 'premium', '/ˈpriːmiəm/', 'noun', '{"zh-TW":["保費","額外費用","優質的"],"en":["an insurance payment","an extra charge","of high quality"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"em","meaning":"buy (買)"}}', 'insurance premium / premium quality / at a premium', '[{"en":"Insurance premiums have increased this year.","zh-TW":"今年保費增加了。"},{"en":"Office space is available at a premium.","zh-TW":"辦公空間以高價提供。"}]', NULL, NULL, 3, 2370, 419),
(2371, 'preparation', '/ˌprɛpəˈreɪʃən/', 'noun', '{"zh-TW":["準備；籌備"],"en":["the process of getting ready"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"par","meaning":"make ready (準備)"},"suffix":{"text":"-ation","meaning":"行為"}}', 'in preparation for / make preparations', '[{"en":"The team is making preparations for the launch.","zh-TW":"團隊正在為發布做準備。"},{"en":"In preparation for the audit, please organize files.","zh-TW":"為準備審計，請整理文件。"}]', '{"verb":"prepare","adjective":"preparatory"}', NULL, 4, 2371, 606),
(2372, 'prepare', '/prɪˈpɛr/', 'verb', '{"zh-TW":["準備"],"en":["to make ready for use or an event"]}', NULL, 'prepare for / well-prepared', '[{"en":"Please prepare the report by Monday.","zh-TW":"請在週一前準備好報告。"},{"en":"We are well-prepared for the audit.","zh-TW":"我們為審計做了充分準備。"}]', '{"verb":"prepare","noun":"preparation","adjective":"prepared"}', NULL, 3, 2372, NULL),
(2373, 'prepayment', '/ˈpriːpeɪmənt/', 'noun', '{"zh-TW":["預付款"],"en":["payment made in advance before goods or services are received"]}', NULL, 'require a prepayment / apply for a prepayment', '[{"en":"A 30% prepayment is required to confirm the order.","zh-TW":"確認訂單需要30%的預付款。"},{"en":"Prepayment reduces default risk for suppliers.","zh-TW":"預付款降低了供應商的違約風險。"}]', '{"verb":"prepay","adjective":"prepaid"}', NULL, 4, 2373, NULL),
(2374, 'prerequisite', '/ˌpriːˈrɛkwɪzɪt/', 'noun', '{"zh-TW":["先修課程；先決條件"],"en":["a course or condition required before taking another"]}', NULL, 'prerequisite course / fulfill prerequisites', '[{"en":"Introduction to Chemistry is a prerequisite for this course.","zh-TW":"化學入門是這門課的先修課程。"},{"en":"Students must meet the prerequisites before enrolling.","zh-TW":"學生在報名前必須滿足先決條件。"}]', '{"adjective":"prerequisite"}', NULL, 4, 2374, NULL),
(2375, 'prescribe', '/prɪˈskraɪb/', 'verb', '{"zh-TW":["規定；指示"],"en":["to state officially what should be done"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"scribe","meaning":"write (寫)"}}', 'prescribed by law / prescribed procedures', '[{"en":"The law prescribes strict penalties.","zh-TW":"法律規定了嚴格的處罰。"},{"en":"Follow the prescribed procedures.","zh-TW":"遵循規定的程序。"}]', '{"noun":"prescription","adjective":"prescribed"}', NULL, 3, 2375, NULL),
(2376, 'prescription', '/prɪˈskrɪpʃən/', 'noun', '{"zh-TW":["處方；藥方"],"en":["an instruction from a doctor to a pharmacist"]}', NULL, 'write a prescription / fill a prescription', '[{"en":"The doctor wrote a prescription for antibiotics.","zh-TW":"醫生開了抗生素的處方。"},{"en":"Take the prescription to the pharmacy to get your medicine.","zh-TW":"將處方帶到藥局領取您的藥物。"}]', '{"verb":"prescribe","adjective":"prescribed"}', NULL, 4, 2376, NULL),
(2377, 'presence', '/ˈprɛzəns/', 'noun', '{"zh-TW":["存在；出席","風範"],"en":["the state of being present","a person''s bearing"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"sens","meaning":"be (存在)"}}', 'in the presence of / online presence / market presence', '[{"en":"The company has a strong online presence.","zh-TW":"公司有強大的線上存在感。"},{"en":"Your presence at the meeting is required.","zh-TW":"你需出席會議。"}]', '{"adjective":"present","verb":"present"}', NULL, 3, 2377, NULL),
(2378, 'present', '/prɪˈzɛnt/', 'verb', '{"zh-TW":["【主要意義-名詞】禮物；現在","【次要意義-形容詞】目前在場的；出席的","【次要意義-動詞】呈現；提出；引起（困難）"],"en":["[primary - noun] a gift; the current time","[secondary - adjective] being in a place; existing now","[secondary - verb] to show, give, or cause something"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"sent","meaning":"be (存在)"}}', 'present a challenge / present findings / those present / present oneself', '[{"en":"The new regulation presents a significant challenge for small businesses.","zh-TW":"新法規對小型企業構成重大挑戰。"},{"en":"All staff members present at the meeting must sign the attendance sheet.","zh-TW":"所有出席會議的員工必須在出席單上簽名。"},{"en":"The auditor presented the financial findings to the board of directors.","zh-TW":"審計師向董事會提交了財務調查結果。"}]', '{"noun":"presentation, presenter","adverb":"presently"}', 'present 重音在第二音節時為動詞，表「提交/呈現/引起」；片語 present a challenge（構成挑戰）是 TOEIC 高頻句型，present 作形容詞「在場的」也常考。', 3, 2378, NULL),
(2379, 'presentation', '/ˌprezənˈteɪʃən/', 'noun', '{"zh-TW":["簡報；演示"],"en":["a formal talk or demonstration to an audience, often with visual aids"]}', NULL, 'deliver a presentation / board presentation / sales presentation', '[{"en":"She gave an impressive presentation to the executive committee.","zh-TW":"她向執行委員會做了令人印象深刻的簡報。"},{"en":"The presentation covered the company''s five-year growth strategy.","zh-TW":"簡報涵蓋了公司的五年增長策略。"}]', '{"verb":"present","noun":"presenter"}', NULL, 4, 2379, 177),
(2380, 'preserve', '/prɪˈzɜːrv/', 'verb', '{"zh-TW":["保存；維護"],"en":["to keep in its original state","to keep safe or maintain"]}', '{"prefix":{"text":"pre-","meaning":"before (預先)"},"root":{"text":"serve","meaning":"keep (保持)"},"logic":"預先保持好，即「保存」。"}', 'preserve wildlife / preserve tradition / well-preserved; preserve the environment / preserve quality', '[{"en":"We must preserve our natural resources.","zh-TW":"我們必須保存自然資源。"},{"en":"The old building has been well preserved.","zh-TW":"這棟老建築保存得很好。"},{"en":"We must preserve the quality of our products.","zh-TW":"我們必須維護產品品質。"},{"en":"Efforts to preserve the environment are ongoing.","zh-TW":"保護環境的努力仍在進行。"}]', '{"noun":"preservation"}', NULL, 3, 2380, NULL),
(2381, 'preside', '/prɪˈzaɪd/', 'verb', '{"zh-TW":["主持；主管"],"en":["to be in charge of a meeting"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"side","meaning":"sit (坐)"}}', 'preside over / preside at a meeting', '[{"en":"The chairman presided over the meeting.","zh-TW":"主席主持了會議。"},{"en":"She presides over a team of 50.","zh-TW":"她管理50人的團隊。"}]', '{"noun":"president, presidency","adjective":"presidential"}', NULL, 3, 2381, NULL),
(2382, 'press', '/prɛs/', 'verb', '{"zh-TW":["【主要意義-動詞】按壓；擠壓","【次要意義-名詞】新聞界；媒體","【次要意義-動詞】催促；施壓","【次要意義-動詞/名詞】熨燙；熨斗"],"en":["[primary] to push firmly against something","[secondary - noun] newspapers and journalists collectively","[secondary - verb] to urge someone to do something","[secondary - verb/noun] to iron clothes; the act of ironing"]}', NULL, 'press conference / press release / press for a decision / a good press', '[{"en":"The company issued a press release announcing the merger.","zh-TW":"公司發布了一份宣布合並的新聞稿。"},{"en":"The union has been pressing management for a wage increase.","zh-TW":"工會一直在向管理層施壓要求加薪。"},{"en":"The new product received a good press from industry journalists.","zh-TW":"新產品獲得了業界記者的好評。"}]', '{"noun":"pressure, pressing","adjective":"pressing"}', 'press 作名詞意為「新聞界」（press release = 新聞稿），動詞 press for = 施壓要求，TOEIC 媒體或公關文章必考詞彙，press conference（記者招待會）也是高頻搭配。', 2, 2382, NULL),
(2383, 'pressure', '/ˈprɛʃər/', 'noun', '{"zh-TW":["壓力"],"en":["the force exerted; stress"]}', '{"root":{"text":"press","meaning":"push (推)"},"suffix":{"text":"-ure","meaning":"行為"}}', 'under pressure / put pressure on / peer pressure', '[{"en":"The team is under pressure to meet deadlines.","zh-TW":"團隊有趕截止日期的壓力。"},{"en":"Don''t put too much pressure on yourself.","zh-TW":"別給自己太大壓力。"}]', '{"verb":"pressure, pressurize"}', NULL, 3, 2383, NULL),
(2384, 'presume', '/prɪˈzjuːm/', 'verb', '{"zh-TW":["假定；推測"],"en":["to suppose; to assume"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"sume","meaning":"take (拿)"}}', 'presume that / be presumed to / presumably', '[{"en":"I presume you have read the report.","zh-TW":"我假定你已讀了報告。"},{"en":"He is presumed to be responsible.","zh-TW":"他被認為應負責。"}]', '{"noun":"presumption","adjective":"presumptuous","adverb":"presumably"}', NULL, 3, 2384, NULL),
(2385, 'pretty', '/ˈprɪti/', 'adverb', '{"zh-TW":["相當；漂亮的"],"en":["to a moderately high degree","attractive"]}', NULL, 'pretty good / pretty much', '[{"en":"The results are pretty good.","zh-TW":"結果相當不錯。"},{"en":"We are pretty much done.","zh-TW":"我們差不多完成了。"}]', '{"adjective":"pretty","adverb":"pretty"}', NULL, 2, 2385, NULL),
(2386, 'prevail', '/prɪˈveɪl/', 'verb', '{"zh-TW":["盛行；獲勝"],"en":["to be widespread; to win"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"vail","meaning":"be strong (強大)"}}', 'prevailing conditions / prevail upon / justice prevails', '[{"en":"Common sense prevailed in the end.","zh-TW":"最終常識佔了上風。"},{"en":"Such attitudes still prevail in some companies.","zh-TW":"這種態度在一些公司仍盛行。"}]', '{"adjective":"prevailing, prevalent","noun":"prevalence"}', NULL, 3, 2386, NULL),
(2387, 'prevent', '/prɪˈvent/', 'verb', '{"zh-TW":["預防；阻止","防止；阻止"],"en":["to stop something from happening"]}', '{"prefix":{"text":"pre-","meaning":"before (在前)"},"root":{"text":"vent","meaning":"come (來)"},"logic":"在某事來臨前阻止，即「預防」。"}', 'prevent accidents / prevent disease / prevent from; prevent sth. from happening / prevent damage', '[{"en":"Regular exercise helps prevent heart disease.","zh-TW":"規律運動有助預防心臟病。"},{"en":"The barrier prevents people from falling.","zh-TW":"護欄防止人跌落。"},{"en":"We must prevent this from happening again.","zh-TW":"我們必須防止這再次發生。"},{"en":"Regular maintenance prevents costly repairs.","zh-TW":"定期維護防止昂貴的維修。"}]', '{"noun":"prevention","adjective":"preventive"}', NULL, 3, 2387, NULL),
(2388, 'previous', '/ˈpriːviəs/', 'adjective', '{"zh-TW":["先前的；以前的"],"en":["happening before the current time"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"vi","meaning":"way (路)"}}', 'previous experience / previous year / previous employer', '[{"en":"Do you have any previous experience?","zh-TW":"你有先前的經驗嗎？"},{"en":"Sales increased compared to the previous year.","zh-TW":"銷售比前一年增加了。"}]', '{"adverb":"previously"}', NULL, 3, 2388, 178),
(2389, 'price', '/praɪs/', 'noun', '{"zh-TW":["價格"],"en":["the amount of money for which something is sold"]}', '{"root":{"text":"price","meaning":"value (價值)"},"logic":"源自拉丁語 pretium（價值）。"}', 'price tag / asking price / price range', '[{"en":"The price of gas has gone up again.","zh-TW":"汽油價格又上漲了。"},{"en":"What is the price of this laptop?","zh-TW":"這台筆電的價格是多少？"}]', '{"adjective":"pricey","verb":"price"}', NULL, 2, 2389, NULL),
(2390, 'pricing', 'ˈpraɪsɪŋ', 'noun', '{"zh-TW":["定價；價格策略","標價"],"en":["the process of setting prices","a price structure"]}', NULL, 'competitive pricing/pricing strategy', '[{"en":"Our pricing strategy is very competitive.","zh-TW":"我們的定價策略非常有競爭力。"}]', '{"verb":"price","adjective":"priced"}', NULL, 3, 2390, NULL),
(2391, 'primarily', '/praɪˈmɛrəli/', 'adverb', '{"zh-TW":["主要地"],"en":["mainly; for the most part"]}', '{"root":{"text":"prim","meaning":"first (第一)"},"suffix":{"text":"-arily","meaning":"副詞後綴"}}', 'primarily responsible / primarily focused on', '[{"en":"The company primarily focuses on B2B services.","zh-TW":"公司主要專注於B2B服務。"},{"en":"She is primarily responsible for marketing.","zh-TW":"她主要負責行銷。"}]', '{"adjective":"primary"}', NULL, 3, 2391, NULL),
(2392, 'primary', '/ˈpraɪmeri/', 'adjective', '{"zh-TW":["主要的；首要的"],"en":["most important; main"]}', '{"root":{"text":"prim","meaning":"first (第一)"},"suffix":{"text":"-ary","meaning":"...的"}}', 'primary goal / primary source / primary concern', '[{"en":"Our primary goal is customer satisfaction.","zh-TW":"我們的首要目標是客戶滿意。"},{"en":"Cost reduction is the primary concern.","zh-TW":"降低成本是首要關注。"}]', '{"adverb":"primarily"}', NULL, 3, 2392, 179),
(2393, 'principal', '/ˈprɪnsɪpəl/', 'adjective', '{"zh-TW":["主要的；首要的"],"en":["most important"]}', '{"root":{"text":"princip","meaning":"first (第一)"},"suffix":{"text":"-al","meaning":"...的"}}', 'principal reason / principal investor', '[{"en":"The principal reason for the delay was funding.","zh-TW":"延遲的主要原因是資金。"},{"en":"She is the principal investor in the company.","zh-TW":"她是公司的主要投資者。"}]', '{"adverb":"principally","noun":"principal"}', NULL, 3, 2393, NULL),
(2394, 'principle', '/ˈprɪnsɪpəl/', 'noun', '{"zh-TW":["原則；原理"],"en":["a fundamental truth or rule"]}', '{"root":{"text":"princip","meaning":"first (第一)"}}', 'in principle / basic principle / guiding principle', '[{"en":"In principle, we agree with the proposal.","zh-TW":"原則上我們同意提案。"},{"en":"The company operates on ethical principles.","zh-TW":"公司按道德原則運營。"}]', '{"adjective":"principled"}', NULL, 3, 2394, NULL),
(2395, 'print', 'prɪnt', 'verb', '{"zh-TW":["列印；印刷","印刷出版"],"en":["to produce on paper","to publish"]}', NULL, 'print a document/print copies', '[{"en":"Please print five copies of the agenda.","zh-TW":"請列印五份議程。"}]', '{"noun":"print, printer","adjective":"printed"}', NULL, 2, 2395, NULL),
(2396, 'printer', '/ˈprɪntər/', 'noun', '{"zh-TW":["印表機"],"en":["a device that produces text or images on paper"]}', NULL, 'laser printer / wireless printer', '[{"en":"The wireless printer allows printing from any device.","zh-TW":"無線印表機允許從任何設備列印。"},{"en":"Please replace the printer cartridge when the ink runs low.","zh-TW":"墨水不足時請更換印表機墨匣。"}]', NULL, NULL, 3, 2396, NULL),
(2397, 'prior', '/ˈpraɪər/', 'adjective', '{"zh-TW":["先前的；優先的"],"en":["existing or happening before"]}', '{"root":{"text":"pri","meaning":"before (之前)"}}', 'prior to / prior experience / prior approval', '[{"en":"Prior experience is required for this role.","zh-TW":"這職位需要先前經驗。"},{"en":"Prior to the merger, the company was smaller.","zh-TW":"合併前公司較小。"}]', '{"noun":"priority","verb":"prioritize"}', NULL, 2, 2397, 180),
(2398, 'prioritize', '/praɪˈɒrɪtaɪz/', 'verb', '{"zh-TW":["優先排序；區分輕重緩急"],"en":["to arrange tasks in order of importance or urgency"]}', NULL, 'prioritize tasks / prioritize resources / prioritize effectively', '[{"en":"She learned to prioritize high-impact tasks over routine work.","zh-TW":"她學會了將高影響力任務排在常規工作之前。"},{"en":"The team reprioritized the backlog based on customer feedback.","zh-TW":"團隊根據客戶反饋重新排列了待辦清單的優先順序。"}]', '{"noun":"priority","adjective":"prioritized"}', NULL, 4, 2398, 708),
(2399, 'priority', '/praɪˈɒrəti/', 'noun', '{"zh-TW":["優先事項"],"en":["something regarded as more important than others","something more important than others"]}', '{"root":{"text":"prior","meaning":"before/first (在前/首先)"},"suffix":{"text":"-ity","meaning":"state (狀態)"},"logic":"排在前面的事項，即「優先事項」。"}', 'top priority / give priority to / set priorities', '[{"en":"Safety is our top priority.","zh-TW":"安全是我們的首要之務。"},{"en":"You need to set your priorities.","zh-TW":"你需要排定優先順序。"},{"en":"Customer safety is our top priority.","zh-TW":"客戶安全是首要之務。"}]', '{"verb":"prioritize","adjective":"prior"}', NULL, 3, 2399, 420);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2400, 'privacy', '/ˈpraɪvəsi/', 'noun', '{"zh-TW":["隱私"],"en":["the state of being free from public attention"]}', '{"root":{"text":"priv","meaning":"separate (分離)"},"suffix":{"text":"-acy","meaning":"狀態"}}', 'privacy policy / invasion of privacy / protect privacy', '[{"en":"We take customer privacy seriously.","zh-TW":"我們重視客戶隱私。"},{"en":"Read our privacy policy for more details.","zh-TW":"閱讀我們的隱私政策。"}]', '{"adjective":"private","adverb":"privately"}', NULL, 3, 2400, NULL),
(2401, 'privatization', '/ˌpraɪvɪtɪˈzeɪʃən/', 'noun', '{"zh-TW":["私有化"],"en":["the transfer of a government-owned entity to private ownership"]}', NULL, 'pursue privatization / privatization program', '[{"en":"The privatization of the utility company attracted foreign investors.","zh-TW":"公用事業公司的私有化吸引了外國投資者。"},{"en":"Privatization aims to improve efficiency by introducing market competition.","zh-TW":"私有化旨在通過引入市場競爭提高效率。"}]', '{"verb":"privatize","adjective":"privatized"}', NULL, 5, 2401, NULL),
(2402, 'privilege', '/ˈprɪvɪlɪdʒ/', 'noun', '{"zh-TW":["特權；榮幸"],"en":["a special right or advantage"]}', '{"root":{"text":"priv","meaning":"private (私人)"},"suffix":{"text":"-lege","meaning":"law (法律)"}}', 'executive privilege / it is a privilege to', '[{"en":"It''s a privilege to work with this team.","zh-TW":"與這團隊合作是榮幸。"},{"en":"Access to the lounge is a member privilege.","zh-TW":"進入貴賓室是會員特權。"}]', '{"adjective":"privileged"}', NULL, 3, 2402, NULL),
(2403, 'proactive', '/proʊˈæktɪv/', 'adjective', '{"zh-TW":["積極主動的；前瞻性的"],"en":["taking initiative to deal with issues before they arise"]}', NULL, 'proactive approach / proactive communication / proactive management', '[{"en":"A proactive approach to risk management prevents costly surprises.","zh-TW":"積極主動的風險管理方法防止了代價高昂的意外。"},{"en":"She was praised for her proactive communication with clients.","zh-TW":"她因與客戶的積極主動溝通而受到讚揚。"}]', '{"adverb":"proactively","antonym":"reactive"}', NULL, 3, 2403, 908),
(2404, 'probation', '/prəˈbeɪʃən/', 'noun', '{"zh-TW":["試用期；考察期"],"en":["a period of testing a new employee''s suitability"]}', NULL, 'on probation / three-month probation', '[{"en":"New employees serve a three-month probation period.","zh-TW":"新員工需經過三個月的試用期。"},{"en":"His performance during probation was outstanding.","zh-TW":"他在試用期間的表現非常出色。"}]', '{"verb":"probate","adjective":"probationary"}', NULL, 3, 2404, NULL),
(2405, 'probe', '/proʊb/', 'verb', '{"zh-TW":["探查；調查"],"en":["to investigate thoroughly"]}', NULL, 'probe into / probe the issue', '[{"en":"Investigators probed into the financial fraud.","zh-TW":"調查人員深入調查財務詐欺。"},{"en":"The committee probed the matter further.","zh-TW":"委員會進一步調查此事。"}]', '{"noun":"probe"}', NULL, 2, 2405, NULL),
(2406, 'problem', '/ˈprɒbləm/', 'noun', '{"zh-TW":["問題"],"en":["a matter that is difficult to deal with"]}', NULL, 'solve a problem / no problem', '[{"en":"We need to solve this problem quickly.","zh-TW":"我們需要快速解決這個問題。"},{"en":"No problem, I can handle it.","zh-TW":"沒問題，我可以處理。"}]', '{"noun":"problem","adjective":"problematic"}', NULL, 3, 2406, NULL),
(2407, 'problem-solving', '/ˈprɒbləm sɒlvɪŋ/', 'noun', '{"zh-TW":["解決問題；問題解決能力"],"en":["the process of finding solutions to difficult or complex issues"]}', NULL, 'problem-solving skills / creative problem-solving / problem-solving approach', '[{"en":"Her strong problem-solving skills helped the team overcome obstacles.","zh-TW":"她強大的問題解決能力幫助團隊克服了障礙。"},{"en":"Problem-solving is one of the most valued skills in the workplace.","zh-TW":"問題解決能力是職場最受重視的技能之一。"}]', '{"verb":"solve problems","adjective":"problem-solving"}', NULL, 5, 2407, NULL),
(2408, 'procedure', '/prəˈsiːdʒər/', 'noun', '{"zh-TW":["程序；流程"],"en":["an established or official way of doing something"]}', NULL, 'follow procedure / standard procedure / operating procedure', '[{"en":"All complaints must be handled according to the established procedure.","zh-TW":"所有投訴必須按照既定程序處理。"},{"en":"The procedure was updated to reflect new regulatory requirements.","zh-TW":"程序已更新以反映新的監管要求。"}]', '{"plural":"procedures","adjective":"procedural"}', NULL, 3, 2408, 421),
(2409, 'proceed', '/prəˈsiːd/', 'verb', '{"zh-TW":["繼續進行","繼續；進行"],"en":["to continue with an action","to continue; to go forward"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"ceed","meaning":"go (走)"},"logic":"向前走，即「繼續進行」。"}', 'proceed with / proceed to / proceed as planned', '[{"en":"Please proceed to the next step.","zh-TW":"請繼續下一步。"},{"en":"The project will proceed as planned.","zh-TW":"專案將按計畫進行。"},{"en":"We will proceed with the plan as scheduled.","zh-TW":"我們將按計劃進行。"}]', '{"noun":"procedure","noun2":"proceedings","adjective":"procedural"}', NULL, 3, 2409, 181),
(2410, 'process', '/ˈprɒsɛs/', 'noun', '{"zh-TW":["過程；流程"],"en":["a series of steps; a method"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"cess","meaning":"go (走)"}}', 'hiring process / in the process of / streamline the process', '[{"en":"The hiring process takes about two weeks.","zh-TW":"招聘流程約需兩週。"},{"en":"We are in the process of upgrading the system.","zh-TW":"我們正在升級系統。"}]', '{"verb":"process","noun":"processing, processor"}', NULL, 3, 2410, 182),
(2411, 'processing', 'ˈprɒsɛsɪŋ', 'noun', '{"zh-TW":["處理；加工","辦理"],"en":["handling or treating data","the act of processing"]}', NULL, 'data processing/order processing', '[{"en":"Order processing takes one business day.","zh-TW":"訂單處理需要一個工作日。"}]', '{"verb":"process","adjective":"processed"}', NULL, 4, 2411, NULL),
(2412, 'processor', '/ˈprɒsɛsər/', 'noun', '{"zh-TW":["處理器"],"en":["the part of a computer that performs operations"]}', NULL, 'word processor / multi-core processor', '[{"en":"This laptop has a fast processor.","zh-TW":"這台筆電有一顆快速處理器。"},{"en":"The processor handles millions of calculations.","zh-TW":"處理器處理數百萬次運算。"}]', '{"verb":"process"}', NULL, 3, 2412, NULL),
(2413, 'procure', '/prəˈkjʊr/', 'verb', '{"zh-TW":["獲得；採購"],"en":["to obtain, especially with effort"]}', '{"prefix":{"text":"pro-","meaning":"for"},"root":{"text":"cure","meaning":"care (照料)"}}', 'procure supplies / procure funding', '[{"en":"The department procures supplies from local vendors.","zh-TW":"部門從當地供應商採購物資。"},{"en":"We need to procure additional funding.","zh-TW":"我們需要取得額外資金。"}]', '{"noun":"procurement"}', NULL, 3, 2413, 709),
(2414, 'procurement', '/prəˈkjʊrmənt/', 'noun', '{"zh-TW":["採購"],"en":["the process of obtaining goods or services"]}', NULL, 'procurement department / public procurement', '[{"en":"The procurement department handles all purchasing.","zh-TW":"採購部門處理所有購買事宜。"},{"en":"Public procurement must follow strict rules.","zh-TW":"公共採購必須遵循嚴格的規定。"}]', '{"noun":"procurement","verb":"procure"}', NULL, 4, 2414, 609),
(2415, 'produce', '/ˈprɒdjuːs/', 'noun', '{"zh-TW":["農產品","生產；製造","產生"],"en":["fresh fruits and vegetables","to make or manufacture","to cause"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"duce","meaning":"lead (引導)"},"logic":"向前引導出來的東西，即「產出」。"}', 'fresh produce / local produce; produce goods / produce results / mass-produce', '[{"en":"The supermarket has a large produce section.","zh-TW":"這間超市有很大的生鮮蔬果區。"},{"en":"We buy organic produce from local farms.","zh-TW":"我們從本地農場購買有機農產品。"},{"en":"The factory produces 10,000 units per day.","zh-TW":"工廠每天生產一萬件。"},{"en":"The campaign produced excellent results.","zh-TW":"活動產生了優秀的結果。"}]', '{"verb":"produce","noun":"production","adjective":"productive"}', NULL, 3, 2415, 47),
(2416, 'product', '/ˈprɒdʌkt/', 'noun', '{"zh-TW":["產品"],"en":["something that is manufactured for sale"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"duct","meaning":"lead (引導)"},"logic":"被引導出來的東西，即「產品」。"}', 'new product / product launch', '[{"en":"This product is our best seller.","zh-TW":"這個產品是我們的暢銷品。"},{"en":"The company launched a new product line.","zh-TW":"公司推出了新的產品線。"}]', '{"noun":"production","verb":"produce","adjective":"productive"}', NULL, 3, 2416, NULL),
(2417, 'productive', '/prəˈdʌktɪv/', 'adjective', '{"zh-TW":["有生產力的；多產的"],"en":["producing good results"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"duct","meaning":"lead (引導)"},"suffix":{"text":"-ive","meaning":"...的"}}', 'productive meeting / highly productive', '[{"en":"It was a very productive meeting.","zh-TW":"這是一個非常有成效的會議。"},{"en":"The team has been highly productive.","zh-TW":"團隊生產力很高。"}]', '{"noun":"productivity","adverb":"productively"}', NULL, 4, 2417, NULL),
(2418, 'productivity', '/ˌprɒdʌkˈtɪvɪti/', 'noun', '{"zh-TW":["生產力；效率"],"en":["the rate at which work is completed efficiently"]}', NULL, 'increase productivity / productivity tools', '[{"en":"Remote work tools have boosted employee productivity.","zh-TW":"遠端工作工具提升了員工生產力。"},{"en":"Low morale often leads to reduced productivity.","zh-TW":"士氣低落往往導致生產力下降。"}]', '{"adjective":"productive","adverb":"productively"}', NULL, 4, 2418, 422),
(2419, 'profession', '/prəˈfɛʃən/', 'noun', '{"zh-TW":["職業；專業"],"en":["a type of job requiring special training"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"fess","meaning":"declare (宣稱)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'by profession / medical profession / enter a profession', '[{"en":"She is a lawyer by profession.","zh-TW":"她的職業是律師。"},{"en":"He entered the teaching profession.","zh-TW":"他進入了教學行業。"}]', '{"adjective":"professional","adverb":"professionally","noun":"professional"}', NULL, 4, 2419, NULL),
(2420, 'professional', 'prəˈfɛʃənəl', 'adjective', '{"zh-TW":["專業的；職業的","稱職的"],"en":["relating to a profession","skilled and competent"]}', NULL, 'professional development/professional manner', '[{"en":"Always maintain a professional manner.","zh-TW":"始終保持專業態度。"}]', '{"noun":"professional","adverb":"professionally"}', NULL, 4, 2420, 183),
(2421, 'professionalism', 'prəˈfɛʃənəlɪzəm', 'noun', '{"zh-TW":["專業精神；職業道德","行為規範"],"en":["the conduct expected in a profession","high standards of behavior"]}', NULL, 'show professionalism/maintain professionalism', '[{"en":"Professionalism is expected at all times.","zh-TW":"始終期望展現專業精神。"}]', '{"adjective":"professional","adverb":"professionally"}', NULL, 5, 2421, NULL),
(2422, 'professor', '/prəˈfɛsər/', 'noun', '{"zh-TW":["教授"],"en":["a senior university teacher"]}', NULL, 'assistant professor / professor of history', '[{"en":"The professor published a new paper.","zh-TW":"教授發表了一篇新論文。"},{"en":"She''s a professor of biology.","zh-TW":"她是生物學教授。"}]', NULL, NULL, 3, 2422, NULL),
(2423, 'profile', '/ˈproʊfaɪl/', 'noun', '{"zh-TW":["簡介；概況","形象"],"en":["a description of characteristics","public image"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"fil","meaning":"thread, line (線)"}}', 'company profile / high-profile / raise one''s profile', '[{"en":"Please update your employee profile.","zh-TW":"請更新你的員工資料。"},{"en":"The company maintains a high profile in the industry.","zh-TW":"公司在業界保持高知名度。"}]', '{"verb":"profile","adjective":"high-profile, low-profile"}', NULL, 3, 2423, 184),
(2424, 'profit', '/ˈprɒfɪt/', 'noun', '{"zh-TW":["利潤；收益"],"en":["money gained from business"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"fit","meaning":"make (做)"}}', 'net profit / profit margin / make a profit', '[{"en":"The company made a profit of $1 million.","zh-TW":"公司獲利一百萬美元。"},{"en":"Profit margins have been shrinking.","zh-TW":"利潤率一直在縮減。"}]', '{"adjective":"profitable","noun":"profitability","verb":"profit"}', NULL, 2, 2424, 423),
(2425, 'profitability', 'ˌprɒfɪtəˈbɪlɪti', 'noun', '{"zh-TW":["獲利能力；盈利性","收益"],"en":["the ability to generate profit","financial success"]}', NULL, 'improve profitability/measure profitability', '[{"en":"Improving profitability is a key goal.","zh-TW":"提高獲利能力是主要目標。"}]', '{"adjective":"profitable","adverb":"profitably"}', NULL, 5, 2425, 807),
(2426, 'profitable', '/ˈprɒfɪtəbl/', 'adjective', '{"zh-TW":["有利可圖的；盈利的"],"en":["generating a profit or financial gain"]}', NULL, 'profitable business / highly profitable / profitable venture', '[{"en":"The new product line proved highly profitable in its first year.","zh-TW":"新產品線在第一年被證明是高度有利可圖的。"},{"en":"The company focused on its most profitable segments.","zh-TW":"公司專注於其最有利可圖的細分市場。"}]', '{"adverb":"profitably","noun":"profitability","antonym":"unprofitable"}', NULL, 4, 2426, NULL),
(2427, 'profound', '/prəˈfaʊnd/', 'adjective', '{"zh-TW":["深刻的；深遠的"],"en":["very great or intense"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"found","meaning":"bottom (底部)"}}', 'profound impact / profound effect / profound change', '[{"en":"Technology has had a profound impact on business.","zh-TW":"科技對商業有深遠影響。"},{"en":"The changes are profound and lasting.","zh-TW":"這些變化是深刻且持久的。"}]', '{"adverb":"profoundly","noun":"profundity"}', NULL, 3, 2427, NULL),
(2428, 'program', '/ˈproʊɡræm/', 'noun', '{"zh-TW":["計劃；方案","程式"],"en":["a planned series of activities","software"]}', NULL, 'training program / program development / government program', '[{"en":"The company launched a new training program.","zh-TW":"公司推出了新培訓計劃。"},{"en":"She manages the employee wellness program.","zh-TW":"她管理員工健康方案。"}]', '{"verb":"program","noun":"programmer, programming"}', NULL, 3, 2428, NULL),
(2429, 'progress', '/ˈprɒɡrɛs/', 'noun', '{"zh-TW":["進展；進步"],"en":["forward movement; development"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"gress","meaning":"step (步)"}}', 'make progress / in progress / progress report', '[{"en":"We have made significant progress this month.","zh-TW":"本月我們取得了重大進展。"},{"en":"The project is still in progress.","zh-TW":"項目仍在進行中。"}]', '{"verb":"progress","adjective":"progressive","adverb":"progressively"}', NULL, 3, 2429, 424),
(2430, 'prohibit', '/prəˈhɪbɪt/', 'verb', '{"zh-TW":["禁止"],"en":["to officially forbid","to officially ban"]}', '{"prefix":{"text":"pro-","meaning":"before"},"root":{"text":"hibit","meaning":"hold (持有)"}}', 'prohibit sb. from / strictly prohibited; strictly prohibited / prohibited by law', '[{"en":"Smoking is prohibited in all buildings.","zh-TW":"所有建築物內禁止吸煙。"},{"en":"The law prohibits discrimination.","zh-TW":"法律禁止歧視。"},{"en":"Photography is strictly prohibited.","zh-TW":"嚴禁拍照。"},{"en":"The use of mobile phones is prohibited.","zh-TW":"禁止使用手機。"}]', '{"noun":"prohibition","adjective":"prohibitive"}', NULL, 3, 2430, 710),
(2431, 'project', '/ˈprɒdʒɛkt/', 'noun', '{"zh-TW":["專案；項目"],"en":["a planned piece of work"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"ject","meaning":"throw (投擲)"}}', 'project management / project deadline / project team', '[{"en":"The project is expected to be completed by June.","zh-TW":"項目預計六月完成。"},{"en":"She leads a team of five on the project.","zh-TW":"她帶領五人團隊做該項目。"}]', '{"verb":"project","noun":"projection, projector"}', NULL, 3, 2431, 185),
(2432, 'prolong', '/prəˈlɒŋ/', 'verb', '{"zh-TW":["延長；拖延"],"en":["to make something last longer"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"long","meaning":"long (長)"}}', 'prolong the discussion / prolonged period', '[{"en":"We should not prolong the negotiations.","zh-TW":"我們不應拖延談判。"},{"en":"The prolonged delay caused concern.","zh-TW":"長期延誤引起了擔憂。"}]', '{"adjective":"prolonged","noun":"prolongation"}', NULL, 3, 2432, NULL),
(2433, 'prominent', '/ˈprɒmɪnənt/', 'adjective', '{"zh-TW":["傑出的；顯著的"],"en":["important; well-known"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"min","meaning":"project (突出)"},"suffix":{"text":"-ent","meaning":"...的"}}', 'prominent figure / prominent role / prominently displayed', '[{"en":"She is a prominent figure in the industry.","zh-TW":"她是業界的傑出人物。"},{"en":"The brand is prominently displayed.","zh-TW":"品牌被醒目地展示。"}]', '{"adverb":"prominently","noun":"prominence"}', NULL, 3, 2433, NULL),
(2434, 'promise', '/ˈprɒmɪs/', 'verb', '{"zh-TW":["承諾；保證"],"en":["to tell someone you will do something"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"mis","meaning":"send (送)"}}', 'make a promise / promise to do / show promise', '[{"en":"The company promised to deliver by Monday.","zh-TW":"公司承諾週一前送達。"},{"en":"The new employee shows great promise.","zh-TW":"新員工展現出很大潛力。"}]', '{"noun":"promise","adjective":"promising"}', NULL, 3, 2434, NULL),
(2435, 'promote', '/prəˈmoʊt/', 'verb', '{"zh-TW":["促進；推廣","晉升"],"en":["to help something develop","to give higher rank"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"mote","meaning":"move (移動)"}}', 'promote a product / get promoted / promote growth', '[{"en":"She was promoted to senior manager.","zh-TW":"她被晉升為高級經理。"},{"en":"We need to promote the new product line.","zh-TW":"我們需要推廣新產品線。"}]', '{"noun":"promotion, promoter","adjective":"promotional"}', NULL, 3, 2435, 186),
(2436, 'promotion', '/prəˈmoʊʃn/', 'noun', '{"zh-TW":["促銷；升遷"],"en":["advertising activity","advancement in rank or position"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"mot","meaning":"move (移動)"},"suffix":{"text":"-ion","meaning":"act of (行為)"},"logic":"向前推動的行為，即「促銷」或「升遷」。"}', 'sales promotion / get a promotion', '[{"en":"The store is running a buy-one-get-one promotion.","zh-TW":"商店正在舉辦買一送一的促銷活動。"},{"en":"She received a promotion to senior manager.","zh-TW":"她被升為資深經理。"}]', '{"verb":"promote","adjective":"promotional"}', NULL, 3, 2436, 611),
(2437, 'prompt', '/prɒmpt/', 'adjective', '{"zh-TW":["迅速的；及時的"],"en":["done quickly; immediate"]}', NULL, 'prompt response / prompt delivery / prompt action', '[{"en":"Thank you for your prompt response.","zh-TW":"感謝你的迅速回覆。"},{"en":"Prompt action is required.","zh-TW":"需要立即行動。"}]', '{"adverb":"promptly","verb":"prompt","noun":"promptness"}', NULL, 2, 2437, NULL),
(2438, 'proof', '/pruːf/', 'noun', '{"zh-TW":["證據；證明"],"en":["evidence that shows something is true"]}', NULL, 'proof of identity / burden of proof / proof of purchase', '[{"en":"You need proof of identity to open an account.","zh-TW":"開戶需要身分證明。"},{"en":"Keep the receipt as proof of purchase.","zh-TW":"保留收據作為購買證明。"}]', '{"verb":"prove","adjective":"proven"}', NULL, 2, 2438, NULL),
(2439, 'proofread', '/ˈpruːfriːd/', 'verb', '{"zh-TW":["校對；校讀"],"en":["to read and correct errors in a document"]}', NULL, 'proofread a document / proofread before submitting', '[{"en":"Always proofread your report before submitting it.","zh-TW":"提交前務必校對您的報告。"},{"en":"She proofread the contract carefully for errors.","zh-TW":"她仔細校對了合約中的錯誤。"}]', '{"noun":"proofreader","adjective":"proofread"}', NULL, 3, 2439, NULL),
(2440, 'proper', '/ˈprɒpər/', 'adjective', '{"zh-TW":["適當的；正確的"],"en":["suitable; correct"]}', NULL, 'proper procedure / proper way / proper training', '[{"en":"Please follow the proper procedure.","zh-TW":"請遵循適當程序。"},{"en":"All staff must receive proper training.","zh-TW":"所有員工須接受適當培訓。"}]', '{"adverb":"properly"}', NULL, 2, 2440, NULL),
(2441, 'property', '/ˈprɒpərti/', 'noun', '{"zh-TW":["財產；房產","特性"],"en":["something owned","a characteristic"]}', '{"root":{"text":"propri","meaning":"own (擁有)"},"suffix":{"text":"-ty","meaning":"狀態"}}', 'intellectual property / property management / property value', '[{"en":"The company owns several properties downtown.","zh-TW":"公司在市中心擁有幾處房產。"},{"en":"Intellectual property must be protected.","zh-TW":"智慧財產權必須受到保護。"}]', NULL, NULL, 3, 2441, 425),
(2442, 'proportion', '/prəˈpɔːrʃən/', 'noun', '{"zh-TW":["比例；部分","比例"],"en":["a part of a whole; ratio","a part considered in relation to the whole"]}', '{"prefix":{"text":"pro-","meaning":"for"},"root":{"text":"portion","meaning":"part (部分)"}}', 'in proportion to / a large proportion / out of proportion; in proportion / a high proportion / out of proportion', '[{"en":"A large proportion of the budget goes to R&D.","zh-TW":"預算的大部分用於研發。"},{"en":"Salary should be in proportion to experience.","zh-TW":"薪資應與經驗成比例。"},{"en":"A high proportion of staff are part-time.","zh-TW":"很高比例的員工是兼職的。"},{"en":"Keep expenses in proportion to revenue.","zh-TW":"使支出與收入成比例。"}]', '{"adjective":"proportional, proportionate","adverb":"proportionally"}', NULL, 4, 2442, NULL),
(2443, 'proportional', '/prəˈpɔːrʃənl/', 'adjective', '{"zh-TW":["按比例的；成比例的"],"en":["corresponding in size or degree to something else"]}', NULL, 'proportional representation / proportional allocation', '[{"en":"Costs are allocated proportionally based on usage.","zh-TW":"成本按使用情況按比例分配。"},{"en":"Dividends are paid proportionally to the number of shares held.","zh-TW":"股息按持有股份數量按比例支付。"}]', '{"adverb":"proportionally","noun":"proportion"}', NULL, 4, 2443, 912),
(2444, 'proposal', '/prəˈpoʊzəl/', 'noun', '{"zh-TW":["提案；建議"],"en":["a formal suggestion or plan"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"pos","meaning":"put (放)"},"suffix":{"text":"-al","meaning":"名詞後綴"}}', 'submit a proposal / business proposal / accept a proposal', '[{"en":"The board approved the merger proposal.","zh-TW":"董事會批准了合併提案。"},{"en":"Please submit your proposal by Friday.","zh-TW":"請於週五前提交提案。"}]', '{"verb":"propose","noun":"proposer"}', NULL, 3, 2444, 187),
(2445, 'propose', '/prəˈpoʊz/', 'verb', '{"zh-TW":["提議；求婚","提議；建議"],"en":["to suggest a plan or idea"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"pose","meaning":"put (放置)"},"logic":"把想法放到前面來，即「提議」。"}', 'propose a plan / propose changes / propose a solution; propose a plan / propose changes / propose that', '[{"en":"I propose we postpone the meeting.","zh-TW":"我提議我們延後會議。"},{"en":"She proposed several changes to the plan.","zh-TW":"她對計畫提出了幾項修改建議。"},{"en":"I propose that we postpone the meeting.","zh-TW":"我提議我們推遲會議。"},{"en":"She proposed a new marketing strategy.","zh-TW":"她提出了新的行銷策略。"}]', '{"noun":"proposal"}', NULL, 3, 2445, NULL),
(2446, 'prosecution', '/ˌprɒsɪˈkjuːʃən/', 'noun', '{"zh-TW":["起訴；檢方"],"en":["the process of charging someone with a crime"]}', NULL, 'criminal prosecution / the prosecution rests', '[{"en":"He faces prosecution for fraud.","zh-TW":"他面臨詐欺罪的起訴。"},{"en":"The prosecution presented strong evidence.","zh-TW":"檢方提出了有力的證據。"}]', '{"verb":"prosecute","noun2":"prosecutor"}', NULL, 4, 2446, NULL),
(2447, 'prospect', '/ˈprɒspɛkt/', 'noun', '{"zh-TW":["前景；可能性","潛在客戶","前景；展望"],"en":["the possibility of future success","a potential customer"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"spect","meaning":"look (看)"}}', 'job prospects / future prospects / prospective client; career prospects / bright prospects / prospective buyer', '[{"en":"Job prospects in tech are excellent.","zh-TW":"科技業的就業前景很好。"},{"en":"We have several prospective clients.","zh-TW":"我們有幾個潛在客戶。"},{"en":"Career prospects in this field are bright.","zh-TW":"這個領域的職業前景光明。"},{"en":"We have several prospective buyers.","zh-TW":"我們有幾個潛在買家。"}]', '{"adjective":"prospective","verb":"prospect"}', NULL, 3, 2447, 426),
(2448, 'prospectus', '/prəˈspɛktəs/', 'noun', '{"zh-TW":["公開說明書；招股書"],"en":["a printed document describing a company''s offering"]}', NULL, 'investment prospectus / issue a prospectus', '[{"en":"Read the prospectus before investing.","zh-TW":"投資前請閱讀公開說明書。"},{"en":"The company issued a prospectus for the IPO.","zh-TW":"公司為IPO發行了招股書。"}]', '{"noun":"prospectus"}', NULL, 4, 2448, NULL),
(2449, 'prosperity', '/prɒˈspɛrɪti/', 'noun', '{"zh-TW":["繁榮；興旺"],"en":["the state of being successful"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"sper","meaning":"hope (希望)"},"suffix":{"text":"-ity","meaning":"狀態"}}', 'economic prosperity / bring prosperity', '[{"en":"The policy brought prosperity to the region.","zh-TW":"政策為該地區帶來繁榮。"},{"en":"Economic prosperity depends on stable policies.","zh-TW":"經濟繁榮取決於穩定政策。"}]', '{"adjective":"prosperous","verb":"prosper"}', NULL, 4, 2449, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2450, 'protect', '/prəˈtɛkt/', 'verb', '{"zh-TW":["保護"],"en":["to keep safe from harm"]}', '{"prefix":{"text":"pro-","meaning":"in front of"},"root":{"text":"tect","meaning":"cover (覆蓋)"}}', 'protect against / protect the environment / protect rights', '[{"en":"Laws exist to protect consumers.","zh-TW":"法律的存在是為了保護消費者。"},{"en":"We must protect our intellectual property.","zh-TW":"我們必須保護智慧財產權。"}]', '{"noun":"protection, protector","adjective":"protective"}', NULL, 3, 2450, NULL),
(2451, 'protectionism', '/prəˈtekʃənɪzəm/', 'noun', '{"zh-TW":["保護主義"],"en":["government policies protecting domestic industries from foreign competition"]}', NULL, 'rise of protectionism / protectionism measures / trade protectionism', '[{"en":"Rising protectionism threatens the global trading system.","zh-TW":"保護主義的興起威脅著全球貿易體系。"},{"en":"Import tariffs are a common form of protectionism.","zh-TW":"進口關稅是保護主義的常見形式。"}]', '{"adjective":"protectionist","verb":"protect"}', NULL, 5, 2451, NULL),
(2452, 'protest', '/prəˈtɛst/', 'verb', '{"zh-TW":["抗議；反對"],"en":["to express strong disagreement"]}', '{"prefix":{"text":"pro-","meaning":"forth"},"root":{"text":"test","meaning":"witness (證明)"}}', 'protest against / stage a protest / file a protest', '[{"en":"Workers protested against the pay cuts.","zh-TW":"工人抗議減薪。"},{"en":"The decision was met with strong protests.","zh-TW":"該決定遭到強烈抗議。"}]', '{"noun":"protest, protester"}', NULL, 3, 2452, NULL),
(2453, 'protocol', '/ˈproʊtəkɒl/', 'noun', '{"zh-TW":["協議；通訊協定"],"en":["a set of rules for transmitting data"]}', NULL, 'security protocol / communication protocol', '[{"en":"Follow the security protocol.","zh-TW":"遵循安全協議。"},{"en":"HTTP is a communication protocol.","zh-TW":"HTTP是一種通訊協定。"}]', NULL, NULL, 3, 2453, 427),
(2454, 'prototype', '/ˈproʊtətaɪp/', 'noun', '{"zh-TW":["原型；雛形"],"en":["a preliminary model of a product used for testing and feedback"]}', NULL, 'build a prototype / prototype testing / functional prototype', '[{"en":"The team built a prototype in two weeks to test the concept.","zh-TW":"團隊在兩週內建立了一個原型來測試概念。"},{"en":"User feedback on the prototype led to significant design changes.","zh-TW":"對原型的用戶反饋導致了重大的設計更改。"}]', '{"verb":"prototype"}', NULL, 3, 2454, NULL),
(2455, 'proud', '/praʊd/', 'adjective', '{"zh-TW":["驕傲的；自豪的"],"en":["feeling pleasure about one''s achievements","feeling deep pleasure from one''s own achievements"]}', '{"root":{"text":"proud","meaning":"valiant (英勇)"},"logic":"源自古法語 prud（英勇的），後指對自身感到光榮。"}', 'proud of / proud moment', '[{"en":"We are proud of our team''s achievement.","zh-TW":"我們為團隊的成就感到自豪。"},{"en":"This is a proud moment for the company.","zh-TW":"這是公司引以為傲的時刻。"},{"en":"Her parents are proud of her accomplishments.","zh-TW":"她的父母為她的成就感到驕傲。"},{"en":"It was a proud moment for the whole team.","zh-TW":"這是全隊引以為傲的時刻。"}]', '{"adjective":"proud","noun":"pride","adverb":"proudly"}', NULL, 2, 2455, NULL),
(2456, 'prove', '/pruːv/', 'verb', '{"zh-TW":["證明；證實"],"en":["to show that something is true"]}', NULL, 'prove that / prove to be / prove successful', '[{"en":"The data proved our hypothesis correct.","zh-TW":"數據證明我們的假設正確。"},{"en":"The investment proved to be profitable.","zh-TW":"投資被證明是有利可圖的。"}]', '{"noun":"proof","adjective":"proven"}', NULL, 2, 2456, NULL),
(2457, 'provide', '/prəˈvaɪd/', 'verb', '{"zh-TW":["提供"],"en":["to give or supply something"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"vide","meaning":"see (看)"}}', 'provide services / provide information / provide support', '[{"en":"We provide 24/7 customer support.","zh-TW":"我們提供全天候客服支援。"},{"en":"The report provides useful information.","zh-TW":"報告提供了有用資訊。"}]', '{"noun":"provider, provision","adjective":"provided"}', NULL, 3, 2457, 188),
(2458, 'provision', '/prəˈvɪʒən/', 'noun', '{"zh-TW":["規定；條款","供應"],"en":["a condition in a law or agreement","the act of providing"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"vis","meaning":"see (看)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'make provisions for / under the provisions of / provision of services', '[{"en":"The contract includes a provision for early termination.","zh-TW":"合約包含提前終止的條款。"},{"en":"Make provisions for unexpected expenses.","zh-TW":"為意外開支做好準備。"}]', '{"adjective":"provisional","verb":"provision"}', NULL, 3, 2458, 428),
(2459, 'provoke', '/prəˈvoʊk/', 'verb', '{"zh-TW":["激起；引發"],"en":["to cause a reaction; to anger"]}', '{"prefix":{"text":"pro-","meaning":"forth"},"root":{"text":"voke","meaning":"call (召喚)"}}', 'provoke a response / provoke debate / provoke anger', '[{"en":"The announcement provoked strong reactions.","zh-TW":"公告引起了強烈反應。"},{"en":"His comments provoked a heated debate.","zh-TW":"他的評論引發了激烈辯論。"}]', '{"noun":"provocation","adjective":"provocative"}', NULL, 3, 2459, NULL),
(2460, 'psychiatry', '/saɪˈkaɪətri/', 'noun', '{"zh-TW":["精神病學；精神科"],"en":["the branch of medicine dealing with mental disorders"]}', NULL, 'psychiatry consultation / psychiatry treatment', '[{"en":"She was referred to psychiatry for depression treatment.","zh-TW":"她被轉介到精神科接受憂鬱症治療。"},{"en":"Psychiatry combines medication and therapy to treat mental illness.","zh-TW":"精神科結合藥物和療法來治療精神疾病。"}]', '{"noun":"psychiatrist","adjective":"psychiatric"}', NULL, 4, 2460, NULL),
(2461, 'psychographic', '/ˌsaɪkəˈɡræfɪk/', 'adjective', '{"zh-TW":["心理圖像的；心理統計的"],"en":["relating to personality, values, lifestyles, and interests of consumers"]}', NULL, 'psychographic segmentation / psychographic profile / psychographic targeting', '[{"en":"Psychographic segmentation helped craft messages that resonated emotionally.","zh-TW":"心理圖像細分幫助製作了能引起情感共鳴的訊息。"},{"en":"The campaign used psychographic data to target eco-conscious consumers.","zh-TW":"該活動使用心理統計數據來針對有環保意識的消費者。"}]', '{"noun":"psychographics"}', NULL, 5, 2461, NULL),
(2462, 'public', '/ˈpʌblɪk/', 'adjective', '{"zh-TW":["公共的；公眾的"],"en":["relating to people in general"]}', '{"root":{"text":"publ","meaning":"people (人民)"}}', 'public sector / public opinion / go public', '[{"en":"The company plans to go public next year.","zh-TW":"公司計劃明年上市。"},{"en":"Public transportation is convenient here.","zh-TW":"這裡的公共交通很方便。"}]', '{"noun":"public, publicity","adverb":"publicly","verb":"publicize"}', NULL, 2, 2462, NULL),
(2463, 'publication', '/ˌpʌblɪˈkeɪʃən/', 'noun', '{"zh-TW":["出版；發表","出版物"],"en":["the act of publishing","a published work"]}', '{"root":{"text":"public","meaning":"public (公共)"},"suffix":{"text":"-ation","meaning":"行為"}}', 'date of publication / scientific publication', '[{"en":"The publication of the report is scheduled for May.","zh-TW":"報告預定五月出版。"},{"en":"She has many academic publications.","zh-TW":"她有很多學術發表。"}]', '{"verb":"publish","noun":"publisher"}', NULL, 4, 2463, NULL),
(2464, 'publish', '/ˈpʌblɪʃ/', 'verb', '{"zh-TW":["出版；發表"],"en":["to make available to the public"]}', '{"root":{"text":"publ","meaning":"people (人民)"},"suffix":{"text":"-ish","meaning":"使..."}}', 'publish a report / publish online / newly published', '[{"en":"The findings were published in a journal.","zh-TW":"研究結果發表在期刊上。"},{"en":"We will publish the results online.","zh-TW":"我們將在網上公佈結果。"}]', '{"noun":"publication, publisher, publishing"}', NULL, 3, 2464, NULL),
(2465, 'pull', '/pʊl/', 'verb', '{"zh-TW":["拉；撤回"],"en":["to draw toward oneself","to withdraw"]}', NULL, 'pull out / pull together', '[{"en":"The investor decided to pull out.","zh-TW":"投資者決定撤資。"},{"en":"Let''s pull together on this project.","zh-TW":"讓我們在這個專案上齊心協力。"}]', '{"verb":"pull","noun":"pull"}', NULL, 1, 2465, NULL),
(2466, 'purchase', '/ˈpɜːrtʃəs/', 'verb', '{"zh-TW":["購買"],"en":["to buy something"]}', '{"prefix":{"text":"pur-","meaning":"forward (向前)"},"root":{"text":"chase","meaning":"pursue (追求)"},"logic":"向前追求某物，即「購買」。"}', 'make a purchase / purchase order; purchase order / purchase online / make a purchase', '[{"en":"Customers can purchase tickets online.","zh-TW":"顧客可以在線上購票。"},{"en":"She made a large purchase at the department store.","zh-TW":"她在百貨公司大量購物。"},{"en":"Customers can purchase products online.","zh-TW":"客戶可以在線上購買產品。"},{"en":"Please fill out a purchase order form.","zh-TW":"請填寫採購訂單。"}]', '{"noun":"purchase","noun2":"purchaser"}', NULL, 3, 2466, 48),
(2467, 'purchaser', '/ˈpɜːrtʃɪsər/', 'noun', '{"zh-TW":["買方；採購方"],"en":["a person or organization that buys goods, services, or assets"]}', NULL, 'identify the purchaser / contract with the purchaser', '[{"en":"The purchaser requested modifications to the standard delivery terms.","zh-TW":"買方要求對標準交貨條款進行修改。"},{"en":"The purchaser must pay within 30 days of receiving the goods.","zh-TW":"買方必須在收到貨物後30天內付款。"}]', '{"verb":"purchase","noun2":"purchase"}', NULL, 3, 2467, NULL),
(2468, 'purpose', 'ˈpɜːrpəs', 'noun', '{"zh-TW":["目的；用途","意圖"],"en":["the reason for doing something","an intended result"]}', NULL, 'main purpose/on purpose', '[{"en":"What is the purpose of this meeting?","zh-TW":"這次會議的目的是什麼？"}]', '{"verb":"purpose","adjective":"purposeful","adverb":"purposefully"}', NULL, 3, 2468, NULL),
(2469, 'pursue', '/pərˈsjuː/', 'verb', '{"zh-TW":["追求；追趕","追求；從事","追求"],"en":["to follow in order to catch","to seek to achieve","to follow or try to achieve","to follow or work toward"]}', '{"prefix":{"text":"pur-","meaning":"forward (向前)"},"root":{"text":"sue","meaning":"follow (跟隨)"},"logic":"向前跟隨追趕，即「追求」。"}', 'pursue a career / pursue a goal / pursue happiness; pursue a career / pursue a goal / pursue opportunities; pursue a career / pursue excellence / pursue a goal', '[{"en":"She decided to pursue a career in medicine.","zh-TW":"她決定追求醫學事業。"},{"en":"He pursued his dream of becoming a writer.","zh-TW":"他追求成為作家的夢想。"},{"en":"She decided to pursue a career in finance.","zh-TW":"她決定從事金融事業。"},{"en":"We will continue to pursue this opportunity.","zh-TW":"我們將繼續追求這機會。"},{"en":"She decided to pursue a master''s degree.","zh-TW":"她決定攻讀碩士學位。"},{"en":"The company pursues excellence in all areas.","zh-TW":"公司在所有領域追求卓越。"}]', '{"noun":"pursuit"}', NULL, 2, 2469, NULL),
(2470, 'push', '/pʊʃ/', 'verb', '{"zh-TW":["推；推動"],"en":["to press forward","to urge strongly"]}', NULL, 'push forward / push back', '[{"en":"We need to push forward with the plan.","zh-TW":"我們需要推進計畫。"},{"en":"The client pushed back on the price.","zh-TW":"客戶對價格提出了異議。"}]', '{"verb":"push","noun":"push"}', NULL, 1, 2470, NULL),
